import { Company, Role, InterviewFlow } from './types'
import companiesData from '@/data/companies.json'
import rolesData from '@/data/roles.json'
import flowsData from '@/data/interview-flows.json'

// Content now lives in curated/sourced JSON under src/data:
//  - companies.json      -> generated by the scraper (npm run scrape:companies), Wikidata-sourced
//  - roles.json          -> curated role taxonomy
//  - interview-flows.json -> curated interview flows
// These exports keep the same shape the rest of the app already imports.

export const companies = companiesData as Company[]
export const roles = rolesData as Role[]
export const interviewFlows = flowsData as InterviewFlow[]

export function getCompanyBySlug(slug: string): Company | undefined {
  return companies.find(c => c.slug === slug)
}

export function getRoleBySlug(slug: string): Role | undefined {
  return roles.find(r => r.slug === slug)
}

export function getInterviewFlow(companySlug: string, roleSlug: string): InterviewFlow | undefined {
  return interviewFlows.find(f => f.companySlug === companySlug && f.roleSlug === roleSlug)
}

export function getFlowsForCompany(companySlug: string): InterviewFlow[] {
  return interviewFlows.filter(f => f.companySlug === companySlug)
}

export function getFlowsForRole(roleSlug: string): InterviewFlow[] {
  return interviewFlows.filter(f => f.roleSlug === roleSlug)
}
